import { Scene } from "./engine/_core/Scene";
import { Sphere } from "./engine/entities/primitives/3d/Sphere";
import { Color } from "./engine/math/Color";

export default class MyScene extends Scene {
    public async run() {
        // Build and style a 3D Sphere
        const sphere = new Sphere(6, 64, 64);
        sphere.material.color = new Color(0.1, 0.6, 1.0, 1.0);
        sphere.material.emColor = new Color(0.0, 0.4, 1.0, 1.0);
        sphere.material.emStrength = 1.0;
        this.add(sphere);

        // Keep the camera slightly shifted
        this.camera.position.set([0, 10, 40]);

        // Keep rotation active
        this.always(() => {
            sphere.transform.rotateWorldY(this.dt * 0.001);
            this.invalidate();
        });

        // Run the scene for 4 seconds, then auto-exit
        await this.wait(4000);
    }
}
